import{_ as a,o as n,c as t,ag as o}from"./chunks/framework.em2JOrjF.js";const u=JSON.parse('{"title":"Onboarding a Project","description":"","frontmatter":{},"headers":[],"relativePath":"reference/workflows/onboarding-project.md","filePath":"reference/workflows/onboarding-project.md"}'),s={name:"reference/workflows/onboarding-project.md"};function r(i,e,l,p,c,d){return n(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="onboarding-a-project" tabindex="-1">Onboarding a Project <a class="header-anchor" href="#onboarding-a-project" aria-label="Permalink to &quot;Onboarding a Project&quot;">​</a></h1><p>From &quot;we&#39;ve signed a new client&quot; to &quot;the team is logging time.&quot; All Owner steps unless noted.</p><hr><h2 id="step-1-create-the-project" tabindex="-1">Step 1: Create the project <a class="header-anchor" href="#step-1-create-the-project" aria-label="Permalink to &quot;Step 1: Create the project&quot;">​</a></h2><blockquote><p>&quot;Create project Nike Rebrand for Nike as Fixed Price for $50,000 with 200 hour budget&quot;</p></blockquote><p>VERA will ask for any missing required fields:</p><ul><li><strong>Type</strong> — always asked if not specified (Retainer / T&amp;M / Fixed Price / Pro Bono / Agile)</li><li><strong>Contract value</strong> — required for Fixed Price</li><li><strong>Hours budget</strong> — required for Retainer (annual), optional for others</li><li><strong>Client</strong> — always required; auto-created if new</li></ul><p><strong>For Agile projects:</strong></p><blockquote><p>&quot;Create project Acme App as Agile for Acme Corp&quot;</p></blockquote><p>Then immediately offer Sprint 1:</p><blockquote><p>&quot;Sprint 1 set up. What&#39;s the contract value for Sprint 1?&quot;</p></blockquote><hr><h2 id="step-2-set-a-deadline-client-projects" tabindex="-1">Step 2: Set a deadline (client projects) <a class="header-anchor" href="#step-2-set-a-deadline-client-projects" aria-label="Permalink to &quot;Step 2: Set a deadline (client projects)&quot;">​</a></h2><blockquote><p>&quot;Set deadline for Nike Rebrand to June 30, 2026&quot;</p></blockquote><p>Deadlines are visible to Owners and Managers. Never shown to Users.</p><p>Retainers and time-off projects don&#39;t need deadlines — they&#39;re ongoing.</p><hr><h2 id="step-3-assign-a-project-manager" tabindex="-1">Step 3: Assign a project manager <a class="header-anchor" href="#step-3-assign-a-project-manager" aria-label="Permalink to &quot;Step 3: Assign a project manager&quot;">​</a></h2><blockquote><p>&quot;Assign @alice as PM for Nike Rebrand&quot;</p></blockquote><p>This promotes Alice to Manager role (if she&#39;s currently a User) and sets her as the project&#39;s PM. Alice must have messaged the bot at least once to be in the system.</p><hr><h2 id="step-4-enable-tasks" tabindex="-1">Step 4: Enable tasks <a class="header-anchor" href="#step-4-enable-tasks" aria-label="Permalink to &quot;Step 4: Enable tasks&quot;">​</a></h2><p>Tasks define what types of work can be logged on this project. Enable the ones that apply:</p><blockquote><p>&quot;Enable Development for Nike Rebrand with a 120 hour budget&quot; &quot;Enable Design for Nike Rebrand with 60 hours&quot; &quot;Enable Project Management for Nike Rebrand&quot;</p></blockquote><p>You can set both a <code>budget_hours</code> and <code>alert_threshold</code> per task. When a task reaches its threshold, VERA flags it.</p><p>To see what tasks are available: &quot;List tasks&quot;</p><hr><h2 id="step-5-create-envelopes-for-the-team-manager-or-owner" tabindex="-1">Step 5: Create envelopes for the team (Manager or Owner) <a class="header-anchor" href="#step-5-create-envelopes-for-the-team-manager-or-owner" aria-label="Permalink to &quot;Step 5: Create envelopes for the team (Manager or Owner)&quot;">​</a></h2><p>The PM distributes the project&#39;s hours budget across team members via envelopes:</p><blockquote><p>&quot;Give Alice 60 hours on Nike Rebrand&quot; &quot;Give Bob 80 hours on Nike Rebrand for development&quot; &quot;Give Carol 60 hours on Nike Rebrand&quot;</p></blockquote><p>The sum of all envelopes should not exceed the project&#39;s total <code>budget_hours</code>. VERA warns if someone is overbooked across all their projects.</p><hr><h2 id="step-6-team-can-start-logging" tabindex="-1">Step 6: Team can start logging <a class="header-anchor" href="#step-6-team-can-start-logging" aria-label="Permalink to &quot;Step 6: Team can start logging&quot;">​</a></h2><p>Team members can now log time:</p><blockquote><p>&quot;3 hours on Nike Rebrand for design&quot;</p></blockquote><p>VERA will confirm with an entry ID. The entry flows automatically to all reports and financial calculations.</p><hr><h2 id="complete-example-fixed-price" tabindex="-1">Complete example (Fixed Price) <a class="header-anchor" href="#complete-example-fixed-price" aria-label="Permalink to &quot;Complete example (Fixed Price)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Owner: Create project Nike Rebrand as Fixed Price for $50,000 with 200 hour budget for Nike</span></span>
<span class="line"><span>VERA: Created Nike Rebrand (Fixed Price, $50,000, 200h).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Owner: Set deadline for Nike Rebrand to June 30</span></span>
<span class="line"><span>VERA: Deadline set for Nike Rebrand: 2026-06-30.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Owner: Assign @alice as PM for Nike Rebrand</span></span>
<span class="line"><span>VERA: Alice Chen assigned as PM for Nike Rebrand and promoted to Manager.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Owner/PM: Enable Development for Nike Rebrand with 120 hour budget</span></span>
<span class="line"><span>VERA: Development enabled for Nike Rebrand (120h budget, 80% threshold).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Owner/PM: Enable Design for Nike Rebrand with 60 hours</span></span>
<span class="line"><span>VERA: Design enabled for Nike Rebrand (60h budget).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PM: Give Alice 60 hours on Nike Rebrand</span></span>
<span class="line"><span>VERA: Allocated 60h to Alice Chen on Nike Rebrand (ID: 17).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PM: Give Bob 80 hours on Nike Rebrand</span></span>
<span class="line"><span>VERA: Allocated 80h to Bob Smith on Nike Rebrand (ID: 18). ⚠️ Bob is now at 95% capacity.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>User (Alice): 4h on Nike Rebrand — design</span></span>
<span class="line"><span>VERA: Logged 4h on Nike Rebrand (Design) (ID: 101).</span></span></code></pre></div><hr><h2 id="retainer-onboarding-differences" tabindex="-1">Retainer onboarding differences <a class="header-anchor" href="#retainer-onboarding-differences" aria-label="Permalink to &quot;Retainer onboarding differences&quot;">​</a></h2><ol><li>No contract value needed — retainers have a monthly fee (set externally)</li><li>No deadline — retainers are ongoing</li><li><code>hours_budget</code> = <strong>annual</strong> hours (e.g. 480 for 40/month)</li><li>Check status monthly with <code>get_retainer_status</code></li></ol><hr><h2 id="agile-onboarding-differences" tabindex="-1">Agile onboarding differences <a class="header-anchor" href="#agile-onboarding-differences" aria-label="Permalink to &quot;Agile onboarding differences&quot;">​</a></h2><ol><li>Create the Agile parent (no budget/contract value on parent)</li><li>Create Sprint 1 immediately with its own contract value and hours budget</li><li>Activate each sprint via <code>update_sprint_status</code> when work begins</li><li>Add subsequent sprints as scope is negotiated</li></ol>`,45)])])}const b=a(s,[["render",r]]);export{u as __pageData,b as default};
